import{_ as n,o as i,c as r,ah as t}from"./chunks/framework.Bja9t6Wf.js";const c=JSON.parse('{"title":"MASTER-DOSSIER: DAS HORTEN-MYSTERIUM","description":"","frontmatter":{},"headers":[],"relativePath":"Premium_Dossier_Master.md","filePath":"Premium_Dossier_Master.md"}'),s={name:"Premium_Dossier_Master.md"};function a(h,e,l,d,o,u){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="master-dossier-das-horten-mysterium" tabindex="-1">MASTER-DOSSIER: DAS HORTEN-MYSTERIUM <a class="header-anchor" href="#master-dossier-das-horten-mysterium" aria-label="Permalink to &quot;MASTER-DOSSIER: DAS HORTEN-MYSTERIUM&quot;">​</a></h1><h2 id="eine-investigative-mockumentary-von-volti-sodala" tabindex="-1">Eine investigative Mockumentary von Volti Sodala <a class="header-anchor" href="#eine-investigative-mockumentary-von-volti-sodala" aria-label="Permalink to &quot;Eine investigative Mockumentary von Volti Sodala&quot;">​</a></h2><h2 id="stand-1-marz-2026" tabindex="-1"><strong>Stand:</strong> 1. März 2026 <a class="header-anchor" href="#stand-1-marz-2026" aria-label="Permalink to &quot;**Stand:** 1. März 2026&quot;">​</a></h2><h3 id="inhaltsverzeichnis" tabindex="-1">INHALTSVERZEICHNIS <a class="header-anchor" href="#inhaltsverzeichnis" aria-label="Permalink to &quot;INHALTSVERZEICHNIS&quot;">​</a></h3><ol><li>Das Konzept</li><li>Das Drehbuch (Teil 1-4)</li><li>Das Recherche-Archiv (Inkl. Pilnacek, Benko, Wöginger)</li><li>Geheime Medien &amp; Dokumente</li></ol><hr><h1 id="das-konzept-das-horten-mysterium" tabindex="-1">Das Konzept: Das Horten-Mysterium <a class="header-anchor" href="#das-konzept-das-horten-mysterium" aria-label="Permalink to &quot;Das Konzept: Das Horten-Mysterium&quot;">​</a></h1><p><strong>Arbeitstitel:</strong> <em>Das Horten-Mysterium: Eine fabelhafte Fiktion von Macht, Geld und Perlen</em></p><h2 id="die-vision" tabindex="-1">Die Vision <a class="header-anchor" href="#die-vision" aria-label="Permalink to &quot;Die Vision&quot;">​</a></h2><p>Diese Mockumentary ist eine satirische und zugleich tiefgründige Auseinandersetzung mit dem Erbe eines der reichsten und umstrittensten Paare der deutsch-österreichischen Geschichte: Heidi und Helmut Horten.</p><p>Wir verbinden historische Fakten mit fiktiven Elementen, um die Absurdität von extremem Reichtum, die Mechanismen der Verdrängung und die Verflechtungen zwischen Kapital und Politik aufzuzeigen.</p><h2 id="die-struktur-4-teile" tabindex="-1">Die Struktur (4 Teile) <a class="header-anchor" href="#die-struktur-4-teile" aria-label="Permalink to &quot;Die Struktur (4 Teile)&quot;">​</a></h2><h3 id="_1-die-schillernde-witwe" tabindex="-1">1. Die schillernde Witwe <a class="header-anchor" href="#_1-die-schillernde-witwe" aria-label="Permalink to &quot;1. Die schillernde Witwe&quot;">​</a></h3><p>Ein Blick auf Heidis Leben nach dem Tod ihres Mannes. Wir zeigen ihren exzentrischen Luxus, ihre Kunstsammlung und ihre Rolle als &quot;Grande Dame&quot; der Gesellschaft.</p><h3 id="_2-der-aufstieg-des-helmut-horten" tabindex="-1">2. Der Aufstieg des Helmut Horten <a class="header-anchor" href="#_2-der-aufstieg-des-helmut-horten" aria-label="Permalink to &quot;2. Der Aufstieg des Helmut Horten&quot;">​</a></h3><p>Wir dokumentieren Helmuts Weg zum Kaufhaus-König. Der Fokus liegt hierbei auf der &quot;Marktbereinigung&quot; der 1930er Jahre.</p><h3 id="_3-das-schicksal-der-verlierer" tabindex="-1">3. Das Schicksal der Verlierer <a class="header-anchor" href="#_3-das-schicksal-der-verlierer" aria-label="Permalink to &quot;3. Das Schicksal der Verlierer&quot;">​</a></h3><p>Was geschah mit denen, die ihre Kaufhäuser abgeben mussten? Wir beleuchten das Schicksal der Gebrüder Alsberg.</p><h3 id="_4-die-politische-liebesgeschichte" tabindex="-1">4. Die politische Liebesgeschichte <a class="header-anchor" href="#_4-die-politische-liebesgeschichte" aria-label="Permalink to &quot;4. Die politische Liebesgeschichte&quot;">​</a></h3><p>Die Beziehung zur ÖVP. Wir widmen uns dem &quot;Regen aus Gold&quot; – den Spenden und der Stückelung.</p><hr><p><em>Dieses Projekt ist eine Gratwanderung zwischen Dokumentation und Satire.</em></p><h1 id="part-1-die-schillernde-witwe" tabindex="-1">Part 1: Die schillernde Witwe <a class="header-anchor" href="#part-1-die-schillernde-witwe" aria-label="Permalink to &quot;Part 1: Die schillernde Witwe&quot;">​</a></h1><p><strong>Arbeitstitel:</strong> <em>Vom Glanz der Stille</em></p><p><strong>Besetzung:</strong> Birgit Minichmayr (Heidi Horten), August Diehl (Der junge Helmut - in Rückblenden), <strong>Udo Samel</strong> (August Wöginger), Oliver Masucci (Der Kurator/Chronist).</p><hr><h2 id="szene-1-das-archiv-des-lachelns" tabindex="-1">Szene 1: Das Archiv des Lächelns <a class="header-anchor" href="#szene-1-das-archiv-des-lachelns" aria-label="Permalink to &quot;Szene 1: Das Archiv des Lächelns&quot;">​</a></h2><p><strong>Ort:</strong> Ein hochmodernes, klimatisiertes Depot in der Nähe von Klagenfurt. <strong>Zeit:</strong> Gegenwart.</p><p>Überall stehen weiße Handschuhe auf polierten Tischen. Die Kamera gleitet über endlose Reihen von Schmuckschatullen. Heidi (Birgit Minichmayr) tritt ins Bild. Sie trägt ein schlichtes, aber unbezahlbares Seidenkleid. Sie öffnet eine Schatulle nach der anderen.</p><p><strong>HEIDI</strong> (leise, fast zärtlich) Das ist nicht nur Schmuck. Das sind konservierte Momente. Helmut sagte immer: „Heidi, Gold weint nicht.“ Er hatte recht. Es glänzt einfach weiter, egal was draußen passiert.</p><p>Sie nimmt ein Collier heraus, die Perlen schimmern im künstlichen Licht.</p><p><strong>HEIDI (Forts.)</strong> Sehen Sie diese Perle? Sie ist ein Punkt. Ein kleiner, weißer Punkt in einer unendlichen Bilanz. Wenn man genug davon hat, sieht man das Bild nicht mehr. Man sieht nur noch das Licht. Das ist mein Pointillismus.</p><hr><h2 id="szene-2-der-perlen-inventur-tango-neu" tabindex="-1">Szene 2: Der Perlen-Inventur-Tango (NEU) <a class="header-anchor" href="#szene-2-der-perlen-inventur-tango-neu" aria-label="Permalink to &quot;Szene 2: Der Perlen-Inventur-Tango (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Der große Spiegelsaal im Palais. <strong>Zeit:</strong> Eine schlaflose Nacht.</p><p>Heidi breitet tausende Perlen auf einem riesigen schwarzen Samttuch aus. Sie beginnt, sie mit einer silbernen Pinzette zu sortieren. Der Rhythmus ihrer Bewegungen wird fast tänzerisch. Im Hintergrund läuft leise eine verzerrte Version eines Walzers.</p><p><strong>HEIDI</strong> (zu einer imaginären Person) Eins für die Stiftung. Eins für die Kunst. Drei für das Schweigen. Und eins... für die Ewigkeit.</p><p>Der Kurator (Oliver Masucci) beobachtet sie aus dem Schatten.</p><p><strong>KURATOR</strong> Madame, die Liste der Spendenanfragen ist gewachsen. Die Politik klopft an. Sie wollen wieder... Regen.</p><p><strong>HEIDI</strong> (ohne aufzusehen) Dann geben wir ihnen Regen, Kurator. Aber nur in Tropfen. Stück für Stück. Wie diese Perlen. Wenn man alles auf einmal gibt, ertrinken sie. Wenn man es stückelt, wächst die Dankbarkeit.</p><hr><h2 id="szene-3-das-schweigen-der-jachten-neu" tabindex="-1">Szene 3: Das Schweigen der Jachten (NEU) <a class="header-anchor" href="#szene-3-das-schweigen-der-jachten-neu" aria-label="Permalink to &quot;Szene 3: Das Schweigen der Jachten (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Deck der <em>Carinthia VII</em>, vor der Küste von Nizza. <strong>Zeit:</strong> Sonnenuntergang.</p><p>Die Kamera zeigt die gewaltigen Ausmaße der Jacht. Es ist so still, dass man nur das sanfte Summen der Generatoren hört. Heidi sitzt am Heck und starrt auf das Kielwasser.</p><p><strong>HEIDI</strong> Helmut liebte das Meer. Er sagte, Wasser hat kein Gedächtnis. Man kann eine Spur ziehen, und Sekunden später ist sie weg. Das ist die Freiheit des Geldes. Es löscht die Spuren seiner eigenen Entstehung.</p><p>Ein steward serviert Champagner in Kristallgläsern, die so dünn sind, dass sie beim bloßen Hinsehen zu brechen scheinen.</p><p><strong>HEIDI (Forts.)</strong> Wissen Sie, was das Problem mit der Geschichte ist? Sie ist zu laut. Sie staubt. Reichtum hingegen ist klinisch rein. Er riecht nach nichts. Außer nach dem Morgen.</p><hr><h2 id="szene-4-die-heidi-gala-–-die-inszenierung-des-nichts-neu" tabindex="-1">Szene 4: Die Heidi-Gala – Die Inszenierung des Nichts (NEU) <a class="header-anchor" href="#szene-4-die-heidi-gala-–-die-inszenierung-des-nichts-neu" aria-label="Permalink to &quot;Szene 4: Die Heidi-Gala – Die Inszenierung des Nichts (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Ein prunkvoller Ballsaal. <strong>Zeit:</strong> Nacht.</p><p>Dutzende Gäste in Abendgarderobe stehen herum. Doch es gibt keine Musik, keine Unterhaltung. Nur das Klicken der Absätze auf dem Marmor. Heidi schreitet wie ein Geist durch die schweigende Menge.</p><p><strong>HEIDI</strong> (Stimme aus dem Off) Die Leute glauben, bei einer Gala geht es um das Zeigen. Aber die wahre Gala ist das Schweigen danach. Der Moment, wenn die Gäste nach Hause gehen und man mit dem Inventar der Nacht allein ist. Dann sieht man, wer einem wirklich gehört.</p><hr><h1 id="teil-4-die-politische-liebesgeschichte" tabindex="-1">Teil 4: Die politische Liebesgeschichte <a class="header-anchor" href="#teil-4-die-politische-liebesgeschichte" aria-label="Permalink to &quot;Teil 4: Die politische Liebesgeschichte&quot;">​</a></h1><p><strong>Arbeitstitel:</strong> <em>Der Regen aus Gold</em></p><p><strong>Besetzung:</strong> Birgit Minichmayr (Heidi Horten), Oliver Masucci (Der Generalsekretär / PR-Berater / Christian Pilnacek), August Diehl (Der Investigative Reporter / Helmut Horten / Gernot Blümel), <strong>Udo Samel</strong> (August Wöginger).</p><hr><h2 id="szene-1-das-hinterzimmer-des-glanzes" tabindex="-1">Szene 1: Das Hinterzimmer des Glanzes <a class="header-anchor" href="#szene-1-das-hinterzimmer-des-glanzes" aria-label="Permalink to &quot;Szene 1: Das Hinterzimmer des Glanzes&quot;">​</a></h2><p><strong>Ort:</strong> Ein vergoldetes Separée in einem Wiener Nobel-Café. <strong>Zeit:</strong> Wahljahr 2017.</p><p>Heidi (Birgit Minichmayr) sitzt entspannt im Samtsessel. Vor ihr liegt ein Scheckbuch, das wie eine Reliquie auf dem Tisch thront. Der Generalsekretär (Oliver Masucci) beugt sich ehrfürchtig vor.</p><p><strong>GENERALSEKRETÄR</strong> Wir brauchen... Stabilität, Madame. Und Stabilität kostet in diesen Zeiten. Die Plakate, die Online-Anzeigen... die Berater...</p><p><strong>HEIDI</strong> (lächelt) Ich liebe Stabilität. Helmut pflegte zu sagen: „Geld ist der Kleber, der die Gesellschaft zusammenhält.“ Aber wenn man zu viel Kleber nimmt, sieht man die Fugen nicht mehr.</p><hr><h2 id="szene-2-der-sketch-der-„spenden-stuckelung-neu" tabindex="-1">Szene 2: Der Sketch der „Spenden-Stückelung“ (NEU) <a class="header-anchor" href="#szene-2-der-sketch-der-„spenden-stuckelung-neu" aria-label="Permalink to &quot;Szene 2: Der Sketch der „Spenden-Stückelung“ (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Ein Büro voller Schredder und Taschenrechner. <strong>Zeit:</strong> Spätnachts.</p><p>Drei Berater in maßgeschneiderten Anzügen (Masucci, Diehl, Minichmayr in Mehrfachrollen) sitzen um einen Berg von 500-Euro-Scheinen. Sie haben eine Schablone vor sich.</p><p><strong>BERATER 1 (Masucci)</strong> Hier haben wir insgesamt 931.000 Euro von Madame. Fast eine Million! Ein prächtiger Brocken. Aber am Stück... am Stück ist er unverdaulich für den Rechnungshof.</p><p><strong>BERATER 2 (Diehl)</strong> Wir brauchen das Skalpell. Wir schneiden es in exakt 49.000-Euro-Häppchen. Nicht 50.000! Bei 50.000 gehen die Sirenen an. Bei 49.000... da herrscht heilige Stille.</p><p><strong>BERATER 3 (Minichmayr)</strong> Es ist wie Pointillismus! 19 Mal 49.000 Euro. Viele kleine Punkte. Wenn man davor steht, sieht man nur lauter nette, diskrete Einzelspenden. Erst wenn man weit weg geht, sieht man... das Imperium.</p><hr><h2 id="szene-3-der-regen-aus-gold-im-parlament-neu" tabindex="-1">Szene 3: Der Regen aus Gold im Parlament (NEU) <a class="header-anchor" href="#szene-3-der-regen-aus-gold-im-parlament-neu" aria-label="Permalink to &quot;Szene 3: Der Regen aus Gold im Parlament (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Der Plenarsaal des österreichischen Nationalrats. <strong>Zeit:</strong> Eine fiktive, surreale Debatte über Transparenz.</p><p>Ein Abgeordneter (August Diehl) hält eine leidenschaftliche Rede über die „Unschuld der Spenderin“. Plötzlich beginnt es von der Decke zu regnen. Aber es ist kein Wasser, sondern goldene Konfetti-Münzen mit Heidis Konterfei. Jede Münze trägt die Prägung „49.000“.</p><p><strong>ABGEORDNETER</strong> (während er die Münzen auffängt) Sehen Sie? Das ist kein Geld! Das ist... Wertschätzung! Das ist bürgerschaftliches Engagement in seiner reinsten, geprägten Form! Wer sind wir, dass wir die Hand beißen, die uns so wunderbar stückelt?</p><p>Die anderen Abgeordneten beginnen, die Münzen mit Regenschirmen aufzufangen, die sie verkehrt herum halten.</p><hr><h2 id="szene-4-das-interview-des-vergessens-neu" tabindex="-1">Szene 4: Das Interview des Vergessens (NEU) <a class="header-anchor" href="#szene-4-das-interview-des-vergessens-neu" aria-label="Permalink to &quot;Szene 4: Das Interview des Vergessens (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Eine Jacht im Mittelmeer. <strong>Zeit:</strong> Gegenwart.</p><p>Heidi wird von einem investigativen Journalisten (August Diehl) interviewt. Der Journalist wirkt erschöpft, Heidi ist strahlend.</p><p><strong>JOURNALIST</strong> Frau Horten, Kritiker sagen, Sie kaufen sich mit Ihren Spenden politischen Einfluss. 931.000 Euro sind kein Pappenstiel.</p><p><strong>HEIDI</strong> (lacht glockenhell) Kaufen? Das ist so ein... kaufmännischer Begriff. Ich nenne es „Ermöglichen“. Ich ermögliche es Politikern, sich auf das Wesentliche zu konzentrieren, ohne sich Sorgen um ihr Budget machen zu müssen. Ist das nicht der Inbegriff von Freiheit?</p><hr><h2 id="szene-5-die-„transparenz-gala-–-die-spitze-der-satire-neu" tabindex="-1">Szene 5: Die „Transparenz-Gala“ – Die Spitze der Satire (NEU) <a class="header-anchor" href="#szene-5-die-„transparenz-gala-–-die-spitze-der-satire-neu" aria-label="Permalink to &quot;Szene 5: Die „Transparenz-Gala“ – Die Spitze der Satire (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Ein prunkvoller Ballsaal, in dem „Transparenz“ als Thema gefeiert wird. <strong>Zeit:</strong> Ein fiktives Gala-Event.</p><p>Jeder Gast trägt eine Maske aus halbtransparentem Plastik. Man sieht die Gesichter, aber sie sind verzerrt.</p><p><strong>ERZÄHLER (Masucci, Off-Stimme)</strong> Sie feierten die Offenheit, während sie die Türen schlossen. Sie nannten es „neuen Stil“, während sie die alten Rezepte Helmuts verfeinerten. Heidi saß in der Mitte, die Sonne ihres eigenen Systems. Jede 49.000-Euro-Tranche auf ihrem Collier entsprach einer kleinen Aufmerksamkeit an eine politische Sektion.</p><p>Heidi tanzt mit einem Minister. Sie flüstert ihm etwas ins Ohr. Er nickt heftig, als würde er eine göttliche Eingebung empfangen.</p><hr><h2 id="szene-6-der-„rechnungshof-albtraum-neu" tabindex="-1">Szene 6: Der „Rechnungshof-Albtraum“ (NEU) <a class="header-anchor" href="#szene-6-der-„rechnungshof-albtraum-neu" aria-label="Permalink to &quot;Szene 6: Der „Rechnungshof-Albtraum“ (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Ein dunkles Archiv, in dem ein einsamer Prüfer (Oliver Masucci) versucht, die Spendenwege nachzuvollziehen. <strong>Zeit:</strong> Nacht.</p><p>Die Aktenordner beginnen sich von selbst zu bewegen. Zahlen hüpfen von den Seiten und bilden Muster an den Wänden.</p><p><strong>PRÜFER</strong> Es ist ein Labyrinth aus Seide und Gold! Man folgt einer 49.000-Euro-Spende und landet bei einer Reitsport-Veranstaltung in Kärnten. Man folgt dem Reitsport und landet bei einem Kunst-Event in Wien. Und am Ende... am Ende steht immer nur ein Name. Aber der Name ist legal. Er ist so legal, dass es weh tut.</p><p>Er wird von einem Berg aus goldenen „Pünktchen“ verschüttet.</p><hr><h2 id="szene-7-das-finale-–-die-ewigkeit-des-kapitals-neu" tabindex="-1">Szene 7: Das Finale – Die Ewigkeit des Kapitals (NEU) <a class="header-anchor" href="#szene-7-das-finale-–-die-ewigkeit-des-kapitals-neu" aria-label="Permalink to &quot;Szene 7: Das Finale – Die Ewigkeit des Kapitals (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Heidis Mausoleum oder eine moderne Kunstgalerie. <strong>Zeit:</strong> In der nahen Zukunft.</p><p>Wir sehen eine riesige Leinwand. Darauf ist Helmut Horten abgebildet, aber das Bild besteht aus Millionen von kleinen Euro-Symbolen. Heidi tritt davor.</p><p><strong>HEIDI</strong> (zum Publikum) Helmut sagte, das Kapital stirbt nie. Er hatte recht. Es wandelt nur seine Form. Früher waren es Kaufhäuser, heute sind es Parlamente. Früher war es die „Marktbereinigung“, heute ist es die „Politikgestaltung“. Aber der Pointillismus bleibt derselbe.</p><p>Sie drückt auf einen Knopf. Das Bild von Helmut verwandelt sich in das Logo einer politischen Partei und dann wieder zurück.</p><hr><h2 id="szene-8-das-begrabnis-des-schweigens-und-die-angst-in-linz" tabindex="-1">Szene 8: Das Begräbnis des Schweigens (und die Angst in Linz) <a class="header-anchor" href="#szene-8-das-begrabnis-des-schweigens-und-die-angst-in-linz" aria-label="Permalink to &quot;Szene 8: Das Begräbnis des Schweigens (und die Angst in Linz)&quot;">​</a></h2><p><strong>Ort:</strong> Eine exklusive Trauerfeier am Wörthersee. Weißer Marmor, schwarze Schleifen, Champagner-Kühler. <strong>Zeit:</strong> Juni 2022 (Rückblende) / Schnitt zu März 2026 (Gegenwart).</p><p>August Wöginger (Udo Samel) steht am Buffet. Er wirkt nicht nervös, sondern eher... überlegt. Er isst ein belegtes Brötchen mit Messer und Gabel. Er telefoniert leise. Im Hintergrund das prunkvolle Foto von Heidi.</p><p><strong>WÖGINGER</strong> (ins Telefon, mit sanftem oberösterreichischen Einschlag) Ja, servus... nein, ich bin gerade am See. Wir verabschieden die Madame. Ja, die 931.000... das ist alles ordentlich verbucht. In Tranchen, wie wir es besprochen haben. Pointillismus, genau.</p><p>Er blickt auf das Foto von Heidi und hebt sein Weinglas minimal.</p><p><strong>WÖGINGER</strong> Wegen Linz... Dienstag, der 3. März. Ich hab&#39; dem Richter schon gesagt: Ich bin kein Bestimmungstäter. Ich bin ein Ermöglicher. Wenn der Thomas Schmid mich fragt, wen wir in Braunau brauchen, dann sag&#39; ich&#39;s ihm. Das ist gelebte Bürgernähe. Die WKStA versteht einfach die ländlichen Strukturen nicht.</p><hr><h2 id="szene-9-die-geisterstunde-der-bilanzen-neu" tabindex="-1">Szene 9: Die Geisterstunde der Bilanzen (NEU) <a class="header-anchor" href="#szene-9-die-geisterstunde-der-bilanzen-neu" aria-label="Permalink to &quot;Szene 9: Die Geisterstunde der Bilanzen (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Heidis leeres Schlafzimmer. <strong>Zeit:</strong> Nacht.</p><p>Wöginger (Udo Samel) schleicht durch den Raum. Er wirkt hier fast wie ein Antiquitätenhändler, der den Wert der Stille schätzt. Er berührt einen seidenen Vorhang. Der Geist von Heidi (Birgit Minichmayr) erscheint im Spiegel.</p><p><strong>HEIDI (GEIST)</strong> August... du sorgst dich um ein Finanzamt im Innviertel? Ich habe ganze Sektionen mit Gold neu gestrichen.</p><p><strong>WÖGINGER</strong> (ruhig, ohne sich umzudrehen) Madame, Ihre Welt war... großzügig. Meine Welt ist heute... kleinkariert. Der Thomas Schmid singt jetzt in Wien, und in Linz wollen sie wissen, warum ein Bürgermeister besser qualifiziert sein soll als eine Beamtin. Sie verstehen nicht, dass Loyalität eine eigene Qualifikation ist.</p><p><strong>HEIDI (GEIST)</strong> Dann lehre sie, August. Lehre sie die Ästhetik der Gefälligkeit. In 49.000er-Schritten.</p><hr><h2 id="szene-10-die-kunst-der-regionalen-intervention-neu" tabindex="-1">Szene 10: Die Kunst der regionalen Intervention (NEU) <a class="header-anchor" href="#szene-10-die-kunst-der-regionalen-intervention-neu" aria-label="Permalink to &quot;Szene 10: Die Kunst der regionalen Intervention (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Ein Hinterzimmer in einem Linzer Gasthof. Dunkles Holz, Hirschgeweihe. <strong>Zeit:</strong> 1. März 2026 (Abends).</p><p>August Wöginger (Udo Samel) sitzt allein an einem runden Stammtisch. Vor ihm liegen die Ausdrucke der Chats. Er trägt eine Lesebrille. Er spricht zu einem imaginären Richterstuhl.</p><p><strong>WÖGINGER</strong> Herr Rat, schauen Sie... wenn ich zum Hörer greife, dann tu&#39; ich das für die Leut&#39;. Das Wort „Intervention“ klingt so nach... Hinterzimmer. Aber wir im Innviertel nennen das „Zusammenrücken“. Dass der Bürgermeister den Posten kriegt, das war eine Strukturmaßnahme. Eine regionale Personalentwicklung. Dass die Frau Scharf... (er macht eine kurze Pause)... eine andere Auffassung von Qualifikation hat, das ist ihr gutes Recht. Aber Politik ist eben mehr als nur Zeugnisnoten.</p><p>Er markiert eine Stelle im Chatverlauf mit einem gelben Stift. Er lächelt fast mitleidig.</p><p><strong>WÖGINGER</strong> Bestimmungstäter? Nein. Ich bin der Dirigent einer sehr leisen Melodie. Und am Dienstag... am Dienstag werde ich den Taktstock halten.</p><p>Er klappt die Akte zu. Es macht ein trockenes, endgültiges Geräusch.</p><hr><h2 id="szene-11-das-budgetloch-ballett" tabindex="-1">Szene 11: Das Budgetloch-Ballett <a class="header-anchor" href="#szene-11-das-budgetloch-ballett" aria-label="Permalink to &quot;Szene 11: Das Budgetloch-Ballett&quot;">​</a></h2><p><strong>Ort:</strong> Ein prunkvoller Saal im Parlament. Im Hintergrund steht die „Sobotka-Orgel“. <strong>Zeit:</strong> Januar 2025 (Rückblende).</p><p>Magnus Brunner (August Diehl) steht vor einer riesigen Leinwand mit Grafiken, die alle steil nach unten zeigen. Wolfgang Sobotka (Oliver Masucci) sitzt am Klavier und spielt eine disharmonische Melodie.</p><p><strong>BRUNNER</strong> Wolfgang, es sind 4,7 Prozent. Das ist kein Loch mehr, das ist ein Krater. Die EU schickt uns bereits Liebesbriefe aus Brüssel.</p><p><strong>SOBOTKA</strong> (ohne vom Klavier aufzusehen) Magnus, du denkst zu linear. Denke pointillistisch! 4,7 Prozent sind nur viele kleine Kommastellen. Wenn man die Grafik richtig beleuchtet, sieht es aus wie... Kunst. Ein abstraktes Werk über die Vergänglichkeit des Steuergeldes.</p><hr><h2 id="szene-12-der-erbe-der-steine" tabindex="-1">Szene 12: Der Erbe der Steine <a class="header-anchor" href="#szene-12-der-erbe-der-steine" aria-label="Permalink to &quot;Szene 12: Der Erbe der Steine&quot;">​</a></h2><p><strong>Ort:</strong> Ein leerstehendes, ehemaliges Horten-Kaufhaus. Überall Staub und Gerüste. <strong>Zeit:</strong> Gegenwart.</p><p>René Benko (Oliver Masucci in einer weiteren Rolle) steht in der Mitte der leeren Halle. Er starrt auf eine alte Gedenktafel für Helmut Horten, die halb abgerissen an der Wand hängt.</p><p><strong>BENKO</strong> (flüsternd) Helmut, du hattest es einfach. Du hattest die Zeitgeschichte auf deiner Seite. Du hast die Häuser genommen, als sie nichts wert waren. Ich habe sie genommen, als sie alles wert waren – zumindest in meinen Büchern.</p><p>Der Geist von Helmut Horten (August Diehl) tritt aus dem Schatten einer Rolltreppe.</p><p><strong>HELMUT (GEIST)</strong> Du hast den Fehler aller Goldgräber gemacht, René. Du hast geglaubt, die Steine seien wichtiger als das Schweigen. Ich habe ein Imperium gebaut, das mich überlebt hat. Du hast ein Imperium gebaut, das dich auffrisst.</p><p><strong>BENKO</strong> Ich wollte den Pointillismus vollenden! Milliarden aus dem Nichts! Ein Mosaik aus Glas und Stahl!</p><p><strong>HELMUT (GEIST)</strong> Glas bricht, René. Und Stahl rostet. Nur die Perle... nur die Perle überdauert. Aber du wolltest ja unbedingt Wolkenkratzer bauen.</p><hr><h2 id="szene-13-der-dirigent-der-verfahren" tabindex="-1">Szene 13: Der Dirigent der Verfahren <a class="header-anchor" href="#szene-13-der-dirigent-der-verfahren" aria-label="Permalink to &quot;Szene 13: Der Dirigent der Verfahren&quot;">​</a></h2><p><strong>Ort:</strong> Ein dunkles, holzgetäfeltes Hinterzimmer in einem Wiener Beisl. <strong>Zeit:</strong> Spätabends (Rückblende).</p><p>Christian Pilnacek (Oliver Masucci in einer Doppelrolle) sitzt an einem kleinen runden Tisch. Er wirkt müde, vor ihm steht ein Glas Wein. Wolfgang Sobotka (August Diehl) lehnt sich über den Tisch.</p><p><strong>SOBOTKA</strong> Christian, wir haben ein Problem. Diese WKStA... sie sind wie Terrier. Sie graben in Dingen herum, die sie nichts angehen. Die Horten-Spenden, die Signa-Bewertungen... es stört die Harmonie.</p><p><strong>PILNACEK</strong> (mit schwerer Stimme) Es sind Verfahren, Wolfgang. Offizielle Ermittlungen. Ich kann nicht einfach...</p><p><strong>SOBOTKA</strong> (unterbricht ihn) Warum drehst du es nicht einfach ab? Ganz diskret. Ein bisschen Sand im Getriebe der Bürokratie. Ein verloren gegangener Akt hier, ein suspendierter Ermittler da. Pointillismus, Christian! Wenn man genug kleine Sandkörner streut, bleibt die Maschine stehen.</p><p><strong>PILNACEK</strong> Sie nehmen alles auf, Wolfgang. Jedes Wort. Die Mauern haben Ohren bekommen.</p><p><strong>SOBOTKA</strong> (lächelt kalt) Dann müssen wir lauter spielen. Mehr Musik, weniger Fakten. Das ist das Geheimnis des Mysteriums.</p><hr><h2 id="szene-14-das-duell-der-prasidenten" tabindex="-1">Szene 14: Das Duell der Präsidenten <a class="header-anchor" href="#szene-14-das-duell-der-prasidenten" aria-label="Permalink to &quot;Szene 14: Das Duell der Präsidenten&quot;">​</a></h2><p><strong>Ort:</strong> Der U-Ausschuss-Saal im Parlament. <strong>Zeit:</strong> Januar 2026 (Gegenwart).</p><p>Walter Rosenkranz (Oliver Masucci in einer neuen Rolle) sitzt am erhöhten Vorsitzenden-Tisch. Er wirkt extrem förmlich, fast wie ein preußischer Richter. Ihm gegenüber sitzt Wolfgang Sobotka (August Diehl) auf der Auskunftspersonen-Bank.</p><p><strong>ROSENKRANZ</strong> (läutet die Glocke) Herr Magister Sobotka, ich muss Sie nochmals fragen: Kannten Sie die Tonaufnahme von Christian Pilnacek, bevor sie im „Beisl“ publik wurde?</p><p><strong>SOBOTKA</strong> (lächelt süffisant) Herr Präsident, Ihre Frage ist... wie soll ich sagen... ein wenig durchschaubar. Wir wissen alle, warum wir hier sind. Sie wollen keine Antworten, Sie wollen eine Show.</p><p><strong>ROSENKRANZ</strong> Wir sind hier, um das „Abdrehen“ von Ermittlungen zu untersuchen. Wenn das eine Show ist, dann ist es die Show Ihrer Partei. Was haben Sie Pilnacek über die Horten-Spenden gesagt?</p><p><strong>SOBOTKA</strong> Ich habe ihm gesagt, dass man Musik nicht abdrehen sollte, solange das Publikum noch tanzt.</p><p><strong>ROSENKRANZ</strong> (kalt) Das Publikum in Rossatz tanzt nicht mehr, Herr Magister. Dort herrscht nur noch Stille. Und wir werden diese Stille jetzt brechen.</p><p>Rosenkranz drückt auf einen Knopf. Über die Lautsprecher im Saal ertönt das Rauschen eines alten Tonbands.</p><hr><h2 id="szene-15-der-beirat-im-nebel" tabindex="-1">Szene 15: Der Beirat im Nebel <a class="header-anchor" href="#szene-15-der-beirat-im-nebel" aria-label="Permalink to &quot;Szene 15: Der Beirat im Nebel&quot;">​</a></h2><p><strong>Ort:</strong> Der Sitzungssaal des COFAG-Untersuchungsausschusses. <strong>Zeit:</strong> Mai 2024 (Rückblende).</p><p>René Benko (Oliver Masucci) sitzt auf der Zeugenbank. Er wird von zwei Justizwachebeamten begleitet (polizeiliche Vorführung). Walter Rosenkranz (August Diehl) führt den Vorsitz.</p><p><strong>ROSENKRANZ</strong> (mit schneidender Stimme) Herr Benko, 18,7 Millionen Euro an COFAG-Förderungen. Warum hat das Chalet N in Lech 1,1 Millionen Euro bekommen, während kleine Wirtshäuser um ihr Überleben kämpften?</p><p><strong>BENKO</strong> (ruhig, fast gelangweilt) Herr Präsident, ich muss mich entschlagen. Laufende Verfahren. Aber eines möchte ich klarstellen: Ich war in all diesen Firmen lediglich... Beirat. Ein freundlicher Gast in meinen eigenen Immobilien. Ich habe keine operativen Entscheidungen getroffen. Ich habe lediglich... visionär beobachtet.</p><p><strong>ROSENKRANZ</strong> Visionär beobachtet? Sie haben den Bundeskanzler geduzt und Minister im Jet herumgeflogen!</p><p><strong>BENKO</strong> Auch das war rein beobachtend. Man sieht im Flugzeug einfach besser, wo die Lücken im Budget klaffen. Und was die 18 Millionen angeht: Das sind doch nur viele kleine Punkte. Pointillismus, Herr Präsident. Das müssten Sie doch verstehen.</p><hr><h2 id="szene-16-die-hure-fur-die-reichen" tabindex="-1">Szene 16: Die Hure für die Reichen <a class="header-anchor" href="#szene-16-die-hure-fur-die-reichen" aria-label="Permalink to &quot;Szene 16: Die Hure für die Reichen&quot;">​</a></h2><p><strong>Ort:</strong> Ein schickes Penthouse-Büro im Goldenen Quartier, Wien. <strong>Zeit:</strong> Dezember 2016 (Rückblende).</p><p>Thomas Schmid (August Diehl) steht am Fenster und blickt über die Stadt. Hinter ihm sitzt René Benko (Oliver Masucci) an einem massiven Schreibtisch. Er schiebt einen Umschlag (oder ein Tablet mit einem Vertragsentwurf) über den Tisch.</p><p><strong>BENKO</strong> Thomas, du verschwendest dein talent im Ministerium. 300.000 fix, 300.000 Bonus. Generalbevollmächtigter bei Signa. Das würde dir gut liegen.</p><p><strong>SCHMID</strong> (dreht sich langsam um, ein gequältes Lächeln auf den Lippen) René, das ist... ein großzügiges Angebot. Aber ich habe hier noch Aufgaben. Die Steuerprüfungen, die Abstimmungen mit HBK...</p><p><strong>BENKO</strong> Eben drum. Du räumst die Hürden aus dem Weg, und wir bauen die Wolkenkratzer. Es ist eine Synergie, Thomas.</p><p><strong>SCHMID</strong> (flüsternd, fast zu sich selbst) Weißt du, was ich mir neulich in einem Chat geschrieben habe? Dass ich im ÖVP-Kabinett hackle. Dass ich die Hure für die Reichen bin.</p><p><strong>BENKO</strong> (lacht laut auf) Aber Thomas! Du bist keine Hure. Du bist ein Dienstleister der obersten Kategorie. Und Dienstleistung auf diesem Niveau... die wird eben exzellent bezahlt. Willkommen im Team.</p><hr><h2 id="szene-17-die-asthetik-der-amnesie" tabindex="-1">Szene 17: Die Ästhetik der Amnesie <a class="header-anchor" href="#szene-17-die-asthetik-der-amnesie" aria-label="Permalink to &quot;Szene 17: Die Ästhetik der Amnesie&quot;">​</a></h2><p><strong>Ort:</strong> Blümels moderne Wiener Stadtwohnung. <strong>Zeit:</strong> Ein Morgen im Februar 2021 (Rückblende).</p><p>Gernot Blümel (August Diehl in einer Doppelrolle) steht im Pyjama im Flur. Es läutet stürmisch an der Tür. Er schaut durch den Spion. Draußen stehen Männer in Windjacken mit der Aufschrift „WKStA“.</p><p><strong>GERNOT</strong> (hektisch flüsternd zu seiner Partnerin) Schatz, sie sind da! Die... Kunstsammler von der Staatsanwaltschaft. Nimm den Kleinen. Und nimm den Laptop.</p><p><strong>PARTNERIN</strong> (Oliver Masucci in Frauenkleidung/Perücke) Gernot, warum soll der Laptop in den Kinderwagen? Der Kleine hat doch schon sein iPad.</p><p><strong>GERNOT</strong> Es ist ein Lernprojekt! Frühkindliche Datenerfassung. Geh spazieren. Ganz unauffällig. Wenn sie fragen: Du weißt von nichts. Ich weiß auch von nichts. Wir sind eine Familie der reinen Gegenwart. Wir haben keine Vergangenheit und definitiv keinen Laptop.</p><p><strong>WKStA-BEAMTE (Off)</strong> Öffnen Sie die Tür! Hausdurchsuchung!</p><p><strong>GERNOT</strong> (atmet tief durch, setzt sein bestes Lächeln auf und öffnet die Tür) Guten Morgen, meine Herren! Kommen Sie doch rein. Suchen Sie etwas Bestimmtes? Ein Klavier vielleicht? Oder ein paar Spendenquittungen? Ich muss Sie allerdings vorwarnen: Mein Gedächtnis hat heute seinen freien Tag.</p><hr><h2 id="szene-18-der-finale-vorhang-des-schweigens" tabindex="-1">Szene 18: Der finale Vorhang des Schweigens <a class="header-anchor" href="#szene-18-der-finale-vorhang-des-schweigens" aria-label="Permalink to &quot;Szene 18: Der finale Vorhang des Schweigens&quot;">​</a></h2><p><strong>Ort:</strong> Eine leere Bühne. <strong>Zeit:</strong> Jetzt.</p><p>Die drei Schauspieler (Diehl, Masucci, Minichmayr) treten aus ihren Rollen. Sie legen ihre Kostüme ab.</p><p><strong>AUGUST DIEHL</strong> Ist es wahr? <strong>OLIVER MASUCCI</strong> Es ist besser als wahr. Es ist dokumentiert. <strong>BIRGIT MINICHMAYR</strong> Es ist eine Mockumentary. Wir können die Wahrheit sagen, solange wir behaupten, es sei erfunden.</p><p>Sie blicken gemeinsam in die Kamera. Im Hintergrund sehen wir das Logo der Webseite: <em>Das Horten-Mysterium</em>.</p><p><strong>FADE OUT.</strong></p><h1 id="das-recherche-archiv" tabindex="-1">DAS RECHERCHE-ARCHIV <a class="header-anchor" href="#das-recherche-archiv" aria-label="Permalink to &quot;DAS RECHERCHE-ARCHIV&quot;">​</a></h1><hr><h1 id="recherche-postenschacher-die-thomas-schmid-chats" tabindex="-1">Recherche: Postenschacher &amp; Die Thomas-Schmid-Chats <a class="header-anchor" href="#recherche-postenschacher-die-thomas-schmid-chats" aria-label="Permalink to &quot;Recherche: Postenschacher &amp; Die Thomas-Schmid-Chats&quot;">​</a></h1><p>&quot;Kriegst eh alles, was du willst.&quot; – Dieser Satz aus den Chats von Thomas Schmid ist zum Symbol für eine Politik geworden, die den Staat als Selbstbedienungsladen für Günstlinge betrachtet.</p><h2 id="der-postenschacher" tabindex="-1">Der Postenschacher <a class="header-anchor" href="#der-postenschacher" aria-label="Permalink to &quot;Der Postenschacher&quot;">​</a></h2><p>Ob die Leitung der ÖBAG oder Vorstandsposten in staatsnahen Betrieben: Qualifikation war oft zweitrangig gegenüber der Loyalität zur &#39;Familie&#39;.</p><h2 id="die-mockumentary-perspektive" tabindex="-1">Die Mockumentary-Perspektive <a class="header-anchor" href="#die-mockumentary-perspektive" aria-label="Permalink to &quot;Die Mockumentary-Perspektive&quot;">​</a></h2><p>Wir zeigen in Teil 4, wie die &#39;jungen Wilden&#39; der Politik versuchen, die Diskretion der alten Horten-Schule zu kopieren, dabei aber kläglich an ihrer eigenen digitalen Spur (Emojis!) scheitern.</p><hr><h1 id="recherche-die-causa-„postenschacher-august-woginger" tabindex="-1">Recherche: Die Causa „Postenschacher“ (August Wöginger) <a class="header-anchor" href="#recherche-die-causa-„postenschacher-august-woginger" aria-label="Permalink to &quot;Recherche: Die Causa „Postenschacher“ (August Wöginger)&quot;">​</a></h1><p><strong>Der Fall des Klubobmanns: Wenn politische Intervention auf Amtsmissbrauch trifft.</strong></p><p>Parallel zu den historischen Machenschaften der Ära Horten bietet die aktuelle politische Landschaft Österreichs reichlich Stoff für unsere Mockumentary. Ein Paradebeispiel für moderne Interventionen ist der Prozess gegen ÖVP-Klubobmann <strong>August Wöginger</strong>, der sich aktuell (Stand Februar/März 2026) vor dem Landesgericht Linz verantworten muss.</p><hr><h2 id="der-vorwurf-bestimmung-zum-amtsmissbrauch" tabindex="-1">Der Vorwurf: Bestimmung zum Amtsmissbrauch <a class="header-anchor" href="#der-vorwurf-bestimmung-zum-amtsmissbrauch" aria-label="Permalink to &quot;Der Vorwurf: Bestimmung zum Amtsmissbrauch&quot;">​</a></h2><p>Die Wirtschafts- und Korruptionsstaatsanwaltschaft (WKStA) wirft August Wöginger vor, im Jahr 2017 bei <strong>Thomas Schmid</strong> (damals Generalsekretär im Finanzministerium) interveniert zu haben.</p><ul><li><strong>Das Ziel:</strong> Einem ÖVP-Bürgermeister aus dem Bezirk Schärding sollte der Posten als Leiter des Finanzamts Braunau-Ried-Schärding verschafft werden.</li><li><strong>Die Problematik:</strong> Eine andere Bewerberin, Christa Scharf, galt laut Bundesverwaltungsgericht als fachlich besser qualifiziert. Sie wurde jedoch übergangen.</li><li><strong>Die Rolle Wögingers:</strong> Er wird als „Bestimmungstäter“ geführt, da er die Entscheidungsträger zur unrechtmäßigen Besetzung angestiftet haben soll.</li></ul><hr><h2 id="aktueller-stand-der-gerichtsverhandlung-februar-2026" tabindex="-1">Aktueller Stand der Gerichtsverhandlung (Februar 2026) <a class="header-anchor" href="#aktueller-stand-der-gerichtsverhandlung-februar-2026" aria-label="Permalink to &quot;Aktueller Stand der Gerichtsverhandlung (Februar 2026)&quot;">​</a></h2><p>Nachdem eine ursprünglich geplante Diversion (Zahlung einer Geldbuße ohne Schuldeingeständnis) durch das Oberlandesgericht Linz aufgehoben wurde, läuft nun die Hauptverhandlung.</p><h3 id="_1-einvernahmen-der-mitangeklagten-26-27-februar-2026" tabindex="-1">1. Einvernahmen der Mitangeklagten (26./27. Februar 2026) <a class="header-anchor" href="#_1-einvernahmen-der-mitangeklagten-26-27-februar-2026" aria-label="Permalink to &quot;1. Einvernahmen der Mitangeklagten (26./27. Februar 2026)&quot;">​</a></h3><p>In den letzten zwei Tagen wurden die zwei mitangeklagten Finanzbeamten getrennt befragt:</p><ul><li><strong>Der Kommissionsvorsitzende (Siegfried M.):</strong> Bekennt sich „nicht schuldig“ und betont die Korrektheit des Hearings.</li><li><strong>Der Personalvertreter (Herbert B.):</strong> Gab zu, dass Thomas Schmid ihn gebeten habe, den Bürgermeister zu unterstützen („dass es der Bürgermeister werden soll“), bestreitet aber, die Bewertung manipuliert zu haben.</li></ul><h3 id="_2-der-nachste-termin-woginger-sagt-aus" tabindex="-1">2. Der nächste Termin: Wöginger sagt aus <a class="header-anchor" href="#_2-der-nachste-termin-woginger-sagt-aus" aria-label="Permalink to &quot;2. Der nächste Termin: Wöginger sagt aus&quot;">​</a></h3><ul><li><strong>3. März 2026:</strong> August Wöginger ist zur persönlichen Einvernahme geladen.</li><li><strong>Strafrahmen:</strong> Im Falle einer Verurteilung drohen sechs Monate bis zu fünf Jahre Haft.</li><li><strong>Politische Folgen:</strong> Wöginger hat bereits angekündigt, auch bei einem Schuldspruch erster Instanz nicht als Klubobmann zurückzutreten.</li></ul><hr><h2 id="bedeutung-fur-das-„horten-mysterium" tabindex="-1">Bedeutung für das „Horten-Mysterium“ <a class="header-anchor" href="#bedeutung-fur-das-„horten-mysterium" aria-label="Permalink to &quot;Bedeutung für das „Horten-Mysterium“&quot;">​</a></h2><p>In unserer Mockumentary ziehen wir Parallelen zwischen der historischen Begünstigung von „Freunden“ (wie Helmut Horten durch das NS-Regime) und dem modernen Postenschacher.</p><ul><li><strong>Das Motiv der „Intervention“:</strong> Es zeigt, dass Macht nicht nur durch Geld (Spenden), sondern auch durch den Zugriff auf staatliche Strukturen (Postenbesetzungen) gefestigt wird.</li><li><strong>Satirische Umsetzung:</strong> Wir planen eine Szene, in der ein fiktiver Politiker versucht, eine Intervention als „regionale Strukturförderung“ umzudeuten – ganz im Stil von Wögingers Verteidigungslinie.</li></ul><hr><p><em>Quellen: Aktuelle Berichterstattung (Trend, Krone, Kurier, OE24) vom 27. Februar 2026, Akten der WKStA.</em></p><h1 id="geheime-medien-dokumente" tabindex="-1">Geheime Medien &amp; Dokumente <a class="header-anchor" href="#geheime-medien-dokumente" aria-label="Permalink to &quot;Geheime Medien &amp; Dokumente&quot;">​</a></h1><p>Hier sammeln wir das (fiktive) Beweismaterial, das unsere Mockumentary stützt. Warnung: Einige dieser Dokumente gelten in bestimmten Kreisen als &quot;nicht existent&quot;.</p><h2 id="📄-leaked-die-sacher-serviette-rekonstruktion" tabindex="-1">📄 Leaked: Die &quot;Sacher-Serviette&quot; (Rekonstruktion) <a class="header-anchor" href="#📄-leaked-die-sacher-serviette-rekonstruktion" aria-label="Permalink to &quot;📄 Leaked: Die &quot;Sacher-Serviette&quot; (Rekonstruktion)&quot;">​</a></h2><p>Dieses Dokument bildet das Herzstück von Teil 4. Es handelt sich um eine Original-Serviette aus dem Hotel Sacher, auf der in Heidis Handschrift (und mit Lippenstift-Abdruck am Rand) die erste strategische Skizze der &quot;Pointillismus-Spenden&quot; festgehalten wurde.</p><div class="info custom-block"><p class="custom-block-title">ANALYSE DES DOKUMENTS</p><ul><li><strong>Notiz 1:</strong> &quot;Gernot anrufen. Er braucht wieder Porto.&quot;</li><li><strong>Notiz 2:</strong> &quot;49k x 20 = ? (Rechner im Tresor prüfen)&quot;</li><li><strong>Skizze:</strong> Ein kleiner Berg aus Punkten, der wie ein Diamant geformt ist.</li></ul></div><h2 id="📜-archiv-fund-der-kaufvertrag" tabindex="-1">📜 Archiv-Fund: Der &quot;Kaufvertrag&quot; <a class="header-anchor" href="#📜-archiv-fund-der-kaufvertrag" aria-label="Permalink to &quot;📜 Archiv-Fund: Der &quot;Kaufvertrag&quot;&quot;">​</a></h2><p>Ein Dokumententwurf für die Übernahme der Alsberg-Häuser aus dem Jahr 1933. Der Preis wurde mehrfach mit Rotstift korrigiert, bis er fast bei Null lag. Ein handschriftlicher Vermerk am Rand lautet: <em>&quot;Marktüblich. Effizient. Erledigt.&quot;</em></p><h2 id="🎙️-ton-protokoll-„das-beisl-testament" tabindex="-1">🎙️ Ton-Protokoll: „Das Beisl-Testament“ <a class="header-anchor" href="#🎙️-ton-protokoll-„das-beisl-testament" aria-label="Permalink to &quot;🎙️ Ton-Protokoll: „Das Beisl-Testament“&quot;">​</a></h2><p>Ein Transkript der heimlich aufgenommenen Tonbänder von Christian Pilnacek aus einem Wiener Lokal (November 2023).</p><div class="warning custom-block"><p class="custom-block-title">VERTRAULICHKEITSSTUFE: ROT</p><ul><li><strong>Pilnacek:</strong> „Die ÖVP war jeden Tag da. Sie wollten wissen, warum ich die Verfahren nicht stoppe. Sobotka hat mich gefragt: &#39;Warum drehst du es nicht ab?&#39;“</li><li><strong>Kontext:</strong> Dieses Gespräch bildet die akustische Basis für Szene 13 in unserer Mockumentary. Es markiert den Zusammenbruch der „unabhängigen“ Justiz-Fassade.</li></ul></div>',228)])])}const m=n(s,[["render",a]]);export{c as __pageData,m as default};
